import type { PrintOpts, UnresolvedRule } from './grammar-graph-types.ts';
import { printGraphNode } from './print.ts';
import type { RuleRef } from './rule-ref.ts';

export interface GraphNodeMeta {
  stackId: number;
  pathId: number;
  stepId: number;
