import type { GraphPointer } from './graph-pointer.ts';

export class Pointers {
  #pointers: Map<string, GraphPointer>;

  constructor(...pointers: GraphPointer[]) {
    this.#pointers = new Map();
    for (const pointer of pointers) {
      this.add(pointer);
